param(
  [Parameter(Mandatory=$true)][ValidateSet('Q600','Q700-B150','Q700-U100','Q700-B200')][string]$Cell,
  [Parameter(Mandatory=$true)][ValidateSet('Plan','Smoke','Execute')][string]$Mode,
  [Parameter(Mandatory=$true)][string]$RunId,
  [string]$ExpectedCommit=''
)
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest
$repo=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$root=Join-Path $repo 'experiment\results\experiment-1-57'; $runDir=Join-Path $root $RunId
$baseCompose=Join-Path $repo 'backend\docker-compose.experiment.yaml'; $fixture=Join-Path $repo 'image\arc.jpg'; $load=Join-Path $repo 'experiment\load\mission-load.js'
$sourceCommit='507e075016728daeaab75a51e7172577efe4c5ce'; $appImage='doeng-exp153-a3-recovery-flux-corrected:latest'; $mockImage='doeng-exp153-a3-recovery-experiment-mock:latest'
$ports=@{app=18510;management=19510;mock=18610;db=18710}; $appUrl="http://127.0.0.1:$($ports.app)"; $managementUrl="http://127.0.0.1:$($ports.management)"; $mockUrl="http://127.0.0.1:$($ports.mock)"
$sourceWorktree=$null; $seedDir=$null; $seedImage=$null; $runtimeCompose=$null; $override=$null; $job=$null; $started=$false
function Save-Json($p,$v){New-Item -ItemType Directory -Force -Path (Split-Path -Parent $p)|Out-Null; $v|ConvertTo-Json -Depth 60|Set-Content -LiteralPath $p -Encoding UTF8}
function C([string[]]$a){& docker compose -p ("doeng-exp157-"+$RunId.ToLowerInvariant()) -f $runtimeCompose -f (Join-Path $runDir 'override.yml') @a; if($LASTEXITCODE-ne 0){throw "COMPOSE_FAILED:$($a -join ' ')"}}
function NodePath{$c=Get-Command node.exe -ErrorAction SilentlyContinue;if($c){return $c.Source};$n=Get-ChildItem (Join-Path $env:USERPROFILE '.cache\codex-runtimes') -Recurse -Filter node.exe -File -ErrorAction SilentlyContinue|Select-Object -First 1 -ExpandProperty FullName;if($n){return $n};throw 'NODE_EXECUTABLE_NOT_FOUND'}
function CellConfig{switch($Cell){'Q600' {return @{token=100;ai=600;storage=100}} 'Q700-B150' {return @{token=150;ai=700;storage=150}} 'Q700-U100' {return @{token=100;ai=700;storage=100}} default {return @{token=200;ai=700;storage=200}}}}
function Inputs{if($ExpectedCommit -and ((git -C $repo rev-parse HEAD).Trim() -ne $ExpectedCommit)){throw 'HEAD_MISMATCH'};foreach($p in @($baseCompose,$fixture,$load)){if(-not(Test-Path $p)){throw "MISSING_INPUT:$p"}};if(Test-Path $runDir){throw "RESULT_COLLISION:$runDir"};$cfg=CellConfig;$sha=(Get-FileHash $fixture -Algorithm SHA256).Hash.ToLowerInvariant();New-Item -ItemType Directory -Force -Path $runDir|Out-Null;Save-Json (Join-Path $runDir 'run-config.json') ([ordered]@{experiment='Exp157';runId=$RunId;cell=$Cell;sourceCommit=$sourceCommit;harnessCommit=(git -C $repo rev-parse HEAD).Trim();fixture='image/arc.jpg';fixtureSha256=$sha;activeMissions=200;initialActiveUsers=200;arrivalMode='staggered';intervalMs=1000;durationMs=15000;drainSeconds=10;clientTimeoutMs=15000;aiDelayMs=2000;storageDelayMs=100;appCpu='2';appMemory='3g';jvm='-Xms512m -Xmx2g -XX:+UseG1GC';dbPool=10;tokenPool="$($cfg.token)/$($cfg.token*1.6)";aiPool="$($cfg.ai)/$($cfg.ai*1.6)";storagePool="$($cfg.storage)/$($cfg.storage*1.6)";admission='OFF';sink='OFF'})}
function Prepare{ $script:sourceWorktree=Join-Path $env:TEMP ("doeng-exp157-source-"+$RunId.ToLowerInvariant()); git -C $repo worktree add --detach $sourceWorktree $sourceCommit|Out-Null;if($LASTEXITCODE-ne 0){throw 'WORKTREE_FAILED'};$dump=Get-ChildItem (Join-Path $repo 'exec') -Recurse -Filter doEng.sql -File|Select-Object -First 1 -ExpandProperty FullName;if(-not$dump){throw 'DB_SEED_NOT_FOUND'};$script:seedDir=Join-Path $env:TEMP ("doeng-exp157-seed-"+$RunId.ToLowerInvariant());New-Item -ItemType Directory -Force -Path $seedDir|Out-Null;Copy-Item $dump (Join-Path $seedDir 'doEng.sql');Copy-Item (Join-Path $repo 'backend\experiment-db\02-mission-completion.sql') (Join-Path $seedDir '02-mission-completion.sql');@('FROM mariadb:10.11','COPY doEng.sql /docker-entrypoint-initdb.d/01-doeng.sql','COPY 02-mission-completion.sql /docker-entrypoint-initdb.d/02-mission-completion.sql')|Set-Content (Join-Path $seedDir 'Dockerfile') -Encoding ASCII;$script:seedImage='doeng-exp157-db-'+$RunId.ToLowerInvariant();docker build --quiet -t $seedImage $seedDir|Out-Null;if($LASTEXITCODE-ne 0){throw 'DB_IMAGE_FAILED'};foreach($img in @($appImage,$mockImage)){docker image inspect $img|Out-Null;if($LASTEXITCODE-ne 0){throw "IMAGE_MISSING:$img"}};$yaml=Get-Content $baseCompose -Raw -Encoding UTF8;$yaml=[regex]::Replace($yaml,'(?m)^\s*-\s*"[^\r\n]*doEng\.sql:/docker-entrypoint\.d[^\r\n]*\r?\n','');$yaml=[regex]::Replace($yaml,'(?m)^\s*-\s*"[^\r\n]*02-mission-completion\.sql:/docker-entrypoint[^\r\n]*\r?\n','');$yaml=$yaml.Replace('image: mariadb:10.11',"image: $seedImage");$src=((Join-Path $sourceWorktree 'backend')-replace '\\','/');$yaml=$yaml.Replace('context: ./doEngGameFlux',"context: $src/doEngGameFlux").Replace('context: ./experiment-mock',"context: $src/experiment-mock");$yaml=[regex]::Replace($yaml,'(?ms)(  experiment-mock:\r?\n)    build:\r?\n      context:[^\r\n]*\r?\n','$1    image: '+$mockImage+"`n");$yaml=[regex]::Replace($yaml,'(?ms)(  flux-corrected:\r?\n)    build:\r?\n      context:[^\r\n]*\r?\n      dockerfile:[^\r\n]*\r?\n','$1    image: '+$appImage+"`n");$yaml=$yaml.Replace('"3307:3306"',('"'+$ports.db+':3306"')).Replace('"9100:9100"',('"'+$ports.mock+':9100"')).Replace('"8000:8000"',('"'+$ports.app+':8000"')).Replace('"8001:8000"',('"'+$ports.app+':8000"')).Replace('"9001:9091"',('"'+$ports.management+':9091"'));$cfg=CellConfig;$shared=$cfg.token+$cfg.ai+$cfg.storage;$sharedPend=[int]($shared*1.6);$ov=@("services:","  experiment-mock:","    cpus: '4.0'","    mem_limit: 1g","    environment:","      MOCK_AI_RESULT: 'true'","      MOCK_AI_DELAY_MS: '2000'","      MOCK_AI_STATUS: '200'","      MOCK_STORAGE_DELAY_MS: '100'","      MOCK_STORAGE_STATUS: '200'","      MOCK_CLOSE_BEFORE_RESPONSE: 'false'","      MOCK_STRICT_AUTH: 'true'","  flux-corrected:","    cpus: '2.0'","    mem_limit: 3g","    environment:","      DOENG_EXTERNAL_POOL_MODE: 'ISOLATED'","      DOENG_SHARED_POOL_MAX_CONNECTIONS: '$shared'","      DOENG_SHARED_POOL_PENDING_MAX_COUNT: '$sharedPend'","      DOENG_TOKEN_POOL_MAX_CONNECTIONS: '$($cfg.token)'","      DOENG_TOKEN_POOL_PENDING_MAX_COUNT: '$([int]($cfg.token*1.6))'","      DOENG_AI_POOL_MAX_CONNECTIONS: '$($cfg.ai)'","      DOENG_AI_POOL_PENDING_MAX_COUNT: '$([int]($cfg.ai*1.6))'","      DOENG_STORAGE_POOL_MAX_CONNECTIONS: '$($cfg.storage)'","      DOENG_STORAGE_POOL_PENDING_MAX_COUNT: '$([int]($cfg.storage*1.6))'","      DOENG_HTTP_PENDING_ACQUIRE_TIMEOUT_MS: '10000'","      DOENG_AI_ADMISSION_ENABLED: 'false'","      DOENG_ADMISSION_MODE: 'OFF'","      DOENG_ADMISSION_SCOPE: 'FULL_PATH'","      DOENG_AI_ADMISSION_MAX_CONCURRENT: '400'","      DOENG_STAGE_OBSERVATION_ENABLED: 'true'","      DOENG_POOL_OBSERVATION_ENABLED: 'true'","      MANAGEMENT_ENDPOINTS_WEB_EXPOSURE_INCLUDE: 'health,metrics,doengexperiment,doengdiagnosticpool,doengdiagnosticstage,doengadmission'","      JAVA_TOOL_OPTIONS: '-Xms512m -Xmx2g -XX:+UseG1GC'");$override=Join-Path $runDir 'override.yml';$ov|Set-Content $override -Encoding UTF8;$script:runtimeCompose=Join-Path $repo ("backend\docker-compose.exp157-"+$RunId.ToLowerInvariant()+'.yaml');Set-Content $runtimeCompose $yaml -Encoding UTF8;Save-Json (Join-Path $runDir 'provenance.json') ([ordered]@{cell=$Cell;sourceCommit=$sourceCommit;appImage=$appImage;mockImage=$mockImage;token=$cfg.token;ai=$cfg.ai;storage=$cfg.storage;shared=$shared;sharedPending=$sharedPend}) }
function Health{for($i=0;$i-lt90;$i++){try{if((Invoke-RestMethod "$managementUrl/actuator/health" -TimeoutSec 2).status -eq 'UP'){return}}catch{};Start-Sleep 1};throw 'HEALTH_TIMEOUT'}
function Collector{ $p=Join-Path $runDir 'provider-metrics.jsonl';$s=Join-Path $runDir 'stage-metrics.jsonl';$r=Join-Path $runDir 'application-resources.jsonl';$m=$managementUrl;$rid=$RunId;$cell=$Cell;$script:job=Start-Job -ScriptBlock {param($p,$s,$r,$m,$rid,$cell);$end=(Get-Date).AddSeconds(35);while((Get-Date)-lt$end){$ts=[DateTime]::UtcNow.ToString('o');foreach($q in @(@($p,'doengdiagnosticpool'),@($s,'doengdiagnosticstage'))){try{$c=(Invoke-WebRequest "$m/actuator/$($q[1])" -UseBasicParsing -TimeoutSec 5).Content;if($c-is[byte[]]){$c=[Text.Encoding]::UTF8.GetString($c)};('{"timestamp":"'+$ts+'","runId":"'+$rid+'","cell":"'+$cell+'","payload":'+$c+'}')|Add-Content $q[0] -Encoding UTF8}catch{('{"timestamp":"'+$ts+'","error":"'+($_.Exception.Message-replace '"','')+'"}')|Add-Content $q[0] -Encoding UTF8}};try{docker stats --no-stream --format '{{.Name}},{{.CPUPerc}},{{.MemUsage}},{{.PIDs}}'|ForEach-Object{('{"timestamp":"'+$ts+'","value":"'+($_-replace '"','')+'"}')|Add-Content $r -Encoding UTF8}}catch{};Start-Sleep 1}} -ArgumentList $p,$s,$r,$m,$rid,$cell }
function Load{ $node=NodePath;$ld=Join-Path $runDir 'load';New-Item -ItemType Directory -Force -Path $ld|Out-Null;$result=Join-Path $ld 'client-results.json';$env:TARGET_URL="$appUrl/game/face";$env:ACTIVE_MISSIONS='200';$env:INITIAL_ACTIVE_USERS='200';$env:ACTIVATION_STEP_USERS='200';$env:INTERVAL_MS='1000';$env:DURATION_MS='15000';$env:REQUEST_TIMEOUT_MS='15000';$env:SCENE_ID='2';$env:ANSWER='happy';$env:AUTH_TOKEN='Bearer experiment-member-15';$env:FIXTURE_PATH=$fixture;$env:EXPERIMENT_RUN_ID=$RunId;$env:IMPLEMENTATION="WEBFLUX-$Cell";$env:RESULT_PATH=$result;$env:PROGRESS_PATH=(Join-Path $ld 'client-progress.jsonl');$env:STOP_USER_ON_TRUE='false';$env:LOAD_SCENARIO='single-success';$env:ARRIVAL_MODE='staggered';$env:ACCOUNTING_MODE='corrected';$env:DRAIN_OBSERVATION_SECONDS='10';$env:MOCK_METRICS_URL="$mockUrl/__metrics";$env:LOAD_STOP_MOCK_METRICS_PATH=(Join-Path $runDir 'load-stop-mock-metrics.json');$env:MOCK_DRAIN_PATH=(Join-Path $runDir 'mock-drain.jsonl');$env:MOCK_DRAIN_SUMMARY_PATH=(Join-Path $runDir 'mock-drain-summary.json');$p=Start-Process $node -ArgumentList $load -WorkingDirectory $repo -RedirectStandardOutput (Join-Path $ld 'stdout.log') -RedirectStandardError (Join-Path $ld 'stderr.log') -PassThru -Wait;Save-Json (Join-Path $runDir 'load-exit.json') ([ordered]@{exitCode=$p.ExitCode});if($p.ExitCode-ne0-or-not(Test-Path $result)){throw 'LOAD_FAILED'};Copy-Item $result (Join-Path $runDir 'load-summary.json') }
function Snapshot{foreach($x in @(@('pool-final.json',"$managementUrl/actuator/doengdiagnosticpool"),@('stage-final.json',"$managementUrl/actuator/doengdiagnosticstage"),@('admission-final.json',"$managementUrl/actuator/doengadmission"),@('mock-final.json',"$mockUrl/__metrics"))){try{Save-Json (Join-Path $runDir $x[0]) (Invoke-RestMethod $x[1] -TimeoutSec 5)}catch{Save-Json (Join-Path $runDir $x[0]) ([ordered]@{status='NOT_AVAILABLE';error=$_.Exception.Message})}};Save-Json (Join-Path $runDir 'db-integrity.json') ([ordered]@{status='REACHABLE_ONLY'})}
Inputs;if($Mode-eq'Plan'){Save-Json (Join-Path $runDir 'plan.json') ([ordered]@{status='PLAN_ONLY';cell=$Cell});exit 0}
try{Prepare;$started=$true;C @('up','-d','--force-recreate','mariadb','experiment-mock','flux-corrected');Health;Save-Json (Join-Path $runDir 'warmup.json') ([ordered]@{status='PASS'});Collector;Start-Sleep 3;Load;Snapshot;Wait-Job $job -Timeout 45|Out-Null;Receive-Job $job -ErrorAction SilentlyContinue|Out-Null;Remove-Job $job -Force;Save-Json (Join-Path $runDir 'validity.json') ([ordered]@{valid=$true;validityScope='EXECUTE';reasons=@()});'EXP157_EXECUTE_PASS'}catch{Save-Json (Join-Path $runDir 'validity.json') ([ordered]@{valid=$false;validityScope='EXECUTE';reasons=@($_.Exception.Message)});throw}finally{if($started){try{C @('logs','--no-color','--timestamps','flux-corrected')|Set-Content (Join-Path $runDir 'application.log') -Encoding UTF8}catch{};try{C @('down','--volumes','--remove-orphans')|Out-Null}catch{}};if($job){Remove-Job $job -Force -ErrorAction SilentlyContinue};if($runtimeCompose-and(Test-Path $runtimeCompose)){Remove-Item $runtimeCompose -Force -ErrorAction SilentlyContinue};if($seedImage){docker image rm -f $seedImage 2>$null|Out-Null};if($seedDir-and(Test-Path $seedDir)){Remove-Item $seedDir -Recurse -Force -ErrorAction SilentlyContinue};if($sourceWorktree-and(Test-Path $sourceWorktree)){git -c ("safe.directory="+$sourceWorktree.Replace('\\','/')) -C $repo worktree remove --force $sourceWorktree 2>$null};git -C $repo worktree prune 2>$null;Save-Json (Join-Path $runDir 'cleanup.json') ([ordered]@{completed=$true})}
